'use strict';

/**
 * `usereye init` — first-run scaffolding (ROADMAP-NEXT Phase 4.3).
 *
 * Creates a starter `usereye.config.js`, ensures `artifacts/usereye` is git-ignored,
 * and optionally writes a GitHub Actions workflow that runs `usereye auto` on PRs.
 * Non-interactive and idempotent (refuses to overwrite an existing config).
 */

const fs = require('fs');
const path = require('path');

const CONFIG_TEMPLATE = `// UserEye — project-agnostic browser perception, accessibility and safe exploratory testing.
// Generated by \`npx usereye init\`. Full reference: README.md (see "Defaults") and
// docs/README.md in the package.
//
// Start the tool quickly against a running app:
//   npx usereye auto --url http://localhost:3000 --mode quick
// Or point at a repo and let it start the app itself (see README "auto").

module.exports = {
  mode: 'standard',
  // baseURL: 'http://localhost:3000',      // already-running app (overrides discovery)
  // command: 'npm run dev',                 // start command when UserEye should boot it
  reportLocale: 'en',
  reportFormat: ['html', 'md', 'sarif'],   // add 'sarif' for GitHub code-scanning upload
  // The four knobs below are written out explicitly for discoverability, but they
  // are exactly UserEye's built-in 7.4.1 defaults — deleting them changes nothing.
  // To restore the pre-7.4.1 "loud" profile instead, use:
  //   recordVideo: true, misclick: { policy: 'aggressive' },
  //   findings: { minConfidence: 'low' }
  recordVideo: 'on-failure',               // default: recorded, discarded on a clean run
  trace: 'on-failure',                     // default (7.5.1): trace.zip discarded on a clean run
  misclick: { policy: 'stable-only' },     // default: hard signals only (quieter deep mode)
  findings: {
    minConfidence: 'medium',   // default: primary list is actionable, not a firehose
    gateConfidence: 'high',    // CI gates count only high-confidence issues
    suppress: [],              // codes/sources to drop, e.g. ['missing-favicon']
    elevate: [],               // force high confidence, e.g. ['insufficient-contrast']
    treatAsSignal: [],         // informational, e.g. ['missing-favicon']
  },
  gates: {
    minAdaptiveScore: 70,
    maxBlocker: 0,
    maxCritical: 0,
    maxUnexpectedBrowserErrors: 0,
    // maxMajor: 3,               // optional cap on surfaced majors
    // failOnNewMajor: true,      // with --compare baseline, fail on regressions only
  },
  // auth: { strategy: 'form', ... },
  // hooks: {},
  // plugins: [],
};
`;

const WORKFLOW_TEMPLATE = version => `name: usereye

on:
  pull_request:
  push:
    branches: [main]

jobs:
  usereye:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - run: npm ci
      - run: npx playwright install --with-deps chromium
      # Baseline for PR regression gating (commit issues-only result.json):
      #   npx usereye auto --mode standard --report-format json > baselines/usereye-standard.json
      - name: UserEye (calm CI profile)
        run: >-
          npx usereye auto --project . --mode standard
          --report-format html,md,sarif
          --video-on-failure --misclick-policy stable-only
      - name: Upload UserEye evidence
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: usereye-\${{ github.run_id }}
          path: artifacts/usereye
          if-no-files-found: warn

# The steps above call the CLI directly so this workflow works the moment you run
# \`usereye init --workflow\`, with nothing to publish first. Once the composite
# Action (action.yml v2) lives in a public repository, they collapse into one step:
#
#      - uses: <your-org>/usereye@v${version.split('.')[0]}
#        with:
#          project: .
#          mode: standard
#          video: on-failure            # calm default; 'always' for forensic runs
#          misclick-policy: stable-only
#          soft-fail: 'true'            # first sprint: report without failing the job
#          extra-args: --report-format html,md,sarif
#
# Generated for UserEye ${version}.
`;

const GITIGNORE = ['# UserEye artifacts', 'artifacts/usereye/', ''];

function appendGitignore(projectDir) {
  const gitignorePath = path.join(projectDir, '.gitignore');
  const existing = fs.existsSync(gitignorePath) ? fs.readFileSync(gitignorePath, 'utf8') : '';
  const toAdd = GITIGNORE.filter(
    line => line && !existing.includes(line.replace(/\//g, '')) && !existing.includes(line),
  );
  const target = toAdd.length
    ? `${existing}${existing.endsWith('\n') || !existing ? '' : '\n'}${toAdd.join('\n')}`
    : existing;
  if (target !== existing) fs.writeFileSync(gitignorePath, target.endsWith('\n') ? target : `${target}\n`);
  return toAdd;
}

function parseInitArgv(argv) {
  const out = { dir: process.cwd(), workflow: false, gitignore: true, help: false };
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === '--help' || token === '-h') out.help = true;
    else if (token === '--no-gitignore') out.gitignore = false;
    else if (token === '--workflow') out.workflow = true;
    else if (token === '--dir') out.dir = argv[++i];
    else if (token && !token.startsWith('--')) out.dir = token;
  }
  return out;
}

const INIT_USAGE = `Usage: usereye init [dir] [--workflow] [--no-gitignore]

Scaffolds a starter usereye.config.js in the target directory, adds
artifacts/usereye to .gitignore, and (with --workflow) writes a GitHub Actions
workflow that runs UserEye on PRs.

Refuses to overwrite an existing usereye.config.js (exit code 2 if present).
`;

// One source of truth, read the same way sarif.js, user-eye.js and bin/usereye.js
// read it. This used to fall back to a hardcoded '7.2.0' when package.json could
// not be read, which would silently pin a generated GitHub Actions workflow to a
// version that does not exist in the archive. A package.json we cannot read is a
// broken install, and guessing a number there is worse than refusing to run.
const TOOL_VERSION = require('../package.json').version;

function runInit(argv = process.argv.slice(2)) {
  const opts = parseInitArgv(argv);
  if (opts.help) {
    process.stdout.write(INIT_USAGE);
    return { exitCode: 0, help: true };
  }
  const projectDir = path.resolve(opts.dir);
  if (!fs.existsSync(projectDir)) {
    process.stderr.write(`Directory not found: ${projectDir}\n`);
    return { exitCode: 2 };
  }
  const configPath = path.join(projectDir, 'usereye.config.js');
  if (fs.existsSync(configPath)) {
    process.stderr.write(`Refusing to overwrite existing ${configPath}\n`);
    return { exitCode: 2 };
  }
  fs.writeFileSync(configPath, CONFIG_TEMPLATE);
  const created = [{ path: configPath }];
  if (opts.gitignore) {
    const toAdd = appendGitignore(projectDir);
    created.push({ path: path.join(projectDir, '.gitignore'), added: toAdd });
  }
  if (opts.workflow) {
    const workflowDir = path.join(projectDir, '.github', 'workflows');
    fs.mkdirSync(workflowDir, { recursive: true });
    const workflowPath = path.join(workflowDir, 'usereye.yml');
    fs.writeFileSync(workflowPath, WORKFLOW_TEMPLATE(TOOL_VERSION));
    created.push({ path: workflowPath });
  }
  for (const item of created)
    process.stdout.write(`  + ${path.relative(projectDir, item.path) || item.path}\n`);
  process.stdout.write('\nUserEye scaffolded. Next: edit usereye.config.js, then run:\n');
  process.stdout.write('  npx usereye auto\n');
  return { exitCode: 0, created };
}

module.exports = { CONFIG_TEMPLATE, WORKFLOW_TEMPLATE, appendGitignore, parseInitArgv, runInit, INIT_USAGE };

// bin/ holds this module but package.json maps only `usereye`, so `usereye init`
// is the supported entry point. Invoking the file directly used to be a silent
// no-op — the worst outcome for anyone debugging. Behave like the subcommand.
if (require.main === module) process.exit(runInit(process.argv.slice(2)).exitCode);
